import { title } from "node:process";
import { pool } from "../../db";
import type { IIssue } from "./issue.interface";
import type { IUser } from "../auth/auth.interface";

class IssueService{
  async createIssue(payload: IIssue, rep_id: number) {
    const {title, description, type, status } = payload;
    const res = await pool.query(`
      INSERT INTO issues(title, description, type, status, reporter_id)
      VALUES($1, $2, $3, COALESCE($4, 'open'), $5) RETURNING *
      `, [title, description, type, status, rep_id]);
    return res.rows[0];
  }

  async getAllIssuesFromDB(query:any) {
    const { sort = "newest", type, status } = query;

    let sql = `SELECT * FROM issues`;
    let conditions = [];
    let values = [];

    if (type) {
      values.push(type);
      conditions.push(`type = $${values.length}`);
    }

    if (status) {
      values.push(status);
      conditions.push(`status = $${values.length}`);
    }

    if (conditions.length > 0) {
      sql += ` WHERE ` + conditions.join(" AND ");
    }

    if (sort === "oldest") {
      sql += ` ORDER BY created_at ASC`;
    } else {
      sql += ` ORDER BY created_at DESC`;
    }

    const issues = await pool.query(sql, values);

    const reporterIds = issues.rows.map(issue => issue.reporter_id);
    const users = await pool.query(`
      SELECT id, name, role FROM users
      WHERE id=ANY($1)
      `, [reporterIds]);
    const issueFormat = issues.rows.map(issue => {
      const reporter = users.rows.find(user => user.id === issue.reporter_id);
      return {
        id: issue.id,
        title: issue.title,
        description: issue.description,
        type: issue.type,
        status: issue.status,
        reporter: {
          id: reporter?.id,
          name: reporter?.name,
          role:reporter?.role,
        },
        created_at: issue.created_at,
        updated_at:issue.updated_at,
      }
    })

    return issueFormat;
  }

  async getSingleIssueFromDB(id: number) {
    const res = await pool.query(`
      SELECT * FROM issues WHERE id=$1
      `, [id]);
    const issue = res.rows[0];
    if (!issue) {
      return null;
    }
    const result = await pool.query(`
      SELECT id, name, role FROM users 
      WHERE id=$1
      `, [issue?.reporter_id]);
    const reporter = result.rows[0];
    // console.log(result.rows[0]);
    return {
      id: issue.id,
      title: issue.title,
      description: issue.description,
      type: issue.type,
      status: issue.status,
      reporter: {
        id: reporter?.id,
        name: reporter?.name,
        role: reporter?.role,
      },
      created_at: issue.created_at,
      updated_at: issue.updated_at,
    };
  }

  async modifyIssue( payload: IIssue, id: number) {
    

    const result = await pool.query(`
      SELECT * FROM issues WHERE id=$1
      `, [id]);
    const issue = result.rows[0];
      const { title, description, type } = payload;
      const res = await pool.query(
        `
      UPDATE issues
      SET title =COALESCE($1,title),
      description=COALESCE($2, description),
      type=COALESCE($3, type)
      WHERE id=$4 RETURNING *
      `,
        [title, description, type, id],
      );
      if (res.rowCount === 0) {
        return null;
      }
      return res.rows[0];
    
  }

  async deleteIssueFromDB(id: number) {
    const res = await pool.query(`
      DELETE FROM issues
      WHERE id=$1 RETURNING *
      `, [id]);
    return res.rowCount ? true : false;
  }
}

export default new IssueService();